from lesson_helpers import *
from bs4 import BeautifulSoup,NavigableString
terms=[
('filtre','filtre glomérulaire','Trois couches, une barrière', '<p>Endothélium capillaire, membrane basale et pédicelles des podocytes constituent la barrière entre sang et espace urinaire. Le filtre laisse former un liquide initial sans cellules sanguines ; la lésion de ses constituants peut associer hématurie et protéinurie.</p><p>Le filtre n’est pas le tubule : une modification de l’excrétion sous diurétique n’établit pas la réparation de la barrière. La morphologie, la protéinurie et la trajectoire de fonction apportent des informations complémentaires.</p>', ['NORMAL-FILTRE','EU-HISTO','EU-IRA']),
('complement','complément','C3/C4 : concentration circulante et mécanisme', '<p>Le dosage sérique du complément apporte un indice de consommation ou de perturbation immunologique. Une baisse de C3 est fréquente dans certaines formes postinfectieuses, mais n’est pas spécifique. Le lupus, une infection active ou une maladie du complément peuvent demander un autre raisonnement.</p><p>La normalité du complément n’exclut pas toutes les glomérulonéphrites. Les dépôts tissulaires et les concentrations circulantes sont deux informations différentes. Un C3 encore bas après douze semaines peut motiver une investigation complémentaire ; une aggravation rénale conduit à agir plus tôt.</p>', ['EU-POSTINF','EU-RPGN','INT-INFECTION']),
('anurie','anurie','Absence d’urine : vérifier le mécanisme et agir', '<p>Une absence d’émission d’urine impose de distinguer défaut de production et obstacle ou rétention. L’examen et l’échographie participent à cette distinction. La durée importe pour les critères de sévérité : une anurie d’au moins douze heures est un critère urinaire de stade3 KDIGO.</p><p>Ne pas attendre cette durée pour prendre en charge un patient instable. Hyperkaliémie, surcharge pulmonaire et acidose peuvent imposer une intervention immédiate. La FI de Lasix mentionne la défaillance rénale avec anurie parmi les contre-indications ; l’escalade automatique du produit n’est pas une réponse universelle.</p>', ['EU-IRA','INT-AKI','FI-LASIX-IV']),
('hyperkaliemie','hyperkaliémie','Le potassium : une complication potentiellement silencieuse', '<p>La baisse d’élimination rénale du potassium, certains médicaments et les transferts cellulaires peuvent favoriser une élévation plasmatique. Une hématurie discrète n’exclut pas cette complication. Le dosage et l’électrocardiogramme répondent à deux questions : quelle concentration et quel retentissement électrique ?</p><p>Des modifications de conduction exposent à un arrêt circulatoire et justifient un traitement immédiat. La décision d’épuration dépend de la gravité et de la réponse, et non d’un seuil isolé de créatinine. Un conseil alimentaire ou un supplément potassique doit être reconsidéré dans ce contexte.</p>', ['EU-IRA','FI-LASIX-IV']),
('biopsie','biopsie','Ce que la biopsie ajoute', '<p>La biopsie ne sert pas seulement à donner un nom. Elle décrit les lésions actives, les dépôts et les cicatrices, ce qui peut modifier le traitement et le pronostic. Son indication dépend de l’incertitude, de la vitesse d’évolution et de la conséquence attendue pour la décision.</p><p>La préparation vérifie notamment pression, hémostase, traitements, anatomie et infection. Les modalités sont adaptées par le centre. Microscopie optique, immunofluorescence et électronique se complètent ; une coupe sélectionnée n’épuise pas l’information du prélèvement.</p>', ['EU-HISTO','INT-GN-GENERAL','INT-INFECTION']),
('endocardite','endocardite','Une infection peut imiter une vascularite', '<p>Une glomérulonéphrite d’endocardite peut associer atteinte rénale, complément bas et parfois ANCA. Une fièvre persistante, un souffle nouveau, une valve prothétique ou un foyer infectieux modifient donc l’interprétation d’une sérologie.</p><p>Rechercher l’infection par les examens adaptés, sans donner automatiquement une immunosuppression sur le seul résultat immunologique. Le traitement du foyer et la prise en charge de la complication rénale sont coordonnés. Le schéma oral d’une pharyngite ne traite pas une endocardite.</p>', ['INT-INFECTION','FI-OSPEN']),
('egfr','débit estimé','Pourquoi l’estimation de filtration devient fragile', '<p>Les équations d’estimation reposent notamment sur une créatinine qui reflète un état relativement stable. Lorsque la concentration change rapidement, elle est en transition : le résultat calculé n’est pas une mesure instantanée fiable de la filtration.</p><p>En phase aiguë, suivre la créatinine, son délai de variation, la diurèse et les complications. Une comparaison à la valeur antérieure est souvent plus instructive qu’un nombre de débit isolé. Ne pas dater une atteinte rénale sur ce résultat seul.</p>', ['EU-IRA','INT-AKI']),
('postinfectieux','postinfectieuse','Après infection ou pendant l’infection ?', '<p>La forme postinfectieuse classique suit un intervalle libre après une infection. KDIGO décrit aussi des glomérulonéphrites pendant une infection active. Cette distinction est essentielle chez l’adulte, notamment avec comorbidités ou foyer profond.</p><p>La figure56 de KDIGO rapporte un antécédent de pharyngite résolue une à deux semaines auparavant, ou d’impétigo quatre à six semaines auparavant. Ces délais sont des indices de la forme classique, pas des critères suffisants ni un calendrier valable pour toutes les infections. Rechercher un foyer toujours actif et vérifier la trajectoire.</p>', ['INT-INFECTION','EU-POSTINF']),
('albuminurie','albuminurie','Albumine et protéines totales : deux mesures', '<p>La protéinurie totale additionne différentes protéines ; l’albuminurie en mesure une composante. Une prédominance d’albumine oriente vers le filtre glomérulaire, mais ne détermine pas seule la cause. Les rapports urinaires doivent être identifiés par leur numérateur et leur unité.</p><p>Ne pas utiliser une valeur de protéines totales dans un seuil défini pour l’albumine. Une protéinurie abondante avec hypoalbuminémie peut révéler une composante néphrotique associée, dont les risques se discutent séparément.</p>', ['EU-SYNDROMES','INT-GN-GENERAL']),
('hemorragie','hémorragie alvéolaire','La dyspnée n’est pas toujours une surcharge', '<p>Dans un syndrome réno-pulmonaire, une atteinte des capillaires alvéolaires peut provoquer un saignement pulmonaire. La dyspnée, l’anémie et parfois l’hémoptysie orientent ; l’expectoration sanglante n’est pas nécessairement présente dès le début.</p><p>Chez un patient glomérulaire, la surcharge hydrosodée est une autre cause de dyspnée. L’évaluation clinique, biologique et thoracique doit distinguer les mécanismes sans retarder les soins urgents. La maladie anti-membrane basale peut atteindre rein et poumon, mais certaines formes restent rénales.</p>', ['CH-URGENCE','EU-RPGN']),
('pauci','pauci-immun','Peu de dépôts visibles, pas absence d’immunité', '<p>Le terme pauci-immun décrit une faible quantité de dépôts immunitaires détectables dans le tissu, en contraste avec des dépôts granuleux ou linéaires abondants. Il ne signifie pas que le processus ne soit pas immunologique.</p><p>Les vascularites associées aux ANCA peuvent produire ce profil. L’interprétation relie histologie, sérologies, signes extrarénaux et recherche d’infection. Un nom de profil histologique ne doit pas être transformé en prescription sans contexte.</p>', ['EU-RPGN','CH-URGENCE']),
('dysmorphie','dysmorphie','La forme des hématies comme indice', '<p>La morphologie des hématies urinaires peut être modifiée après leur passage par le filtre glomérulaire. Les acanthocytes sont particulièrement utiles dans cette orientation ; les HUG décrivent aussi des profils mixtes ou indéterminés.</p><p>Un échantillon ancien ou concentré rend l’interprétation moins fiable. Préciser la méthode, confronter la morphologie à la protéinurie et à la fonction, et ne pas transformer l’absence de dysmorphie en exclusion définitive.</p>', ['CH-SEDIMENT']),
('surcharge','surcharge','Le bilan sodé et hydrique devient visible', '<p>Lorsque les apports de sodium et d’eau dépassent l’excrétion, le volume extracellulaire augmente. La prise de poids, les œdèmes et l’hypertension sont des manifestations du bilan positif ; la congestion pulmonaire peut en être une complication grave.</p><p>Ce mécanisme ne requiert pas une hypoalbuminémie profonde. Le traitement vise les apports et l’excrétion sous surveillance, sans déplétion excessive ni remplissage automatique. Une résistance avec menace respiratoire peut conduire à l’épuration extrarénale.</p>', ['EU-IRA','FI-LASIX-IV']),
('immunofluorescence','immunofluorescence','Voir où se trouvent les protéines immunitaires', '<p>Cette technique utilise des anticorps pour rechercher dans le tissu les immunoglobulines, certains composants du complément et d’autres marqueurs. La disposition du signal — granuleuse, linéaire ou peu abondante — contribue à orienter le mécanisme.</p><p>Elle complète la microscopie optique, qui décrit notamment prolifération et cicatrices, et la microscopie électronique, qui précise l’ultrastructure. La coloration PAS d’une photographie ne montre pas directement un signal d’IgG ou deC3.</p>', ['EU-HISTO','EU-RPGN','INT-INFECTION'])
]
pops=[]
for k,term,title,body,ids in terms:pops.append('<template data-pop="n00-'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
for part in ['a','b','c','d']:
 p=CH/('N00_'+part+'.html');s=BeautifulSoup(p.read_text(),'html.parser')
 for k,term,_,_,_ in terms:
  inserted=0
  for node in list(s.find_all(string=True)):
   if inserted>=2:break
   if not isinstance(node,NavigableString) or any(x.name in ['button','a','style','script','h1','h2','h3','h4','th','figcaption'] for x in node.parents):continue
   text=str(node)
   if term not in text:continue
   before,after=text.split(term,1);button=s.new_tag('button',attrs={'class':'w','data-k':'n00-'+k});button.string=term
   node.replace_with(NavigableString(before),button,NavigableString(after));inserted+=1
 p.write_text(str(s)+'\n')
pp=CH/'N00_pop1.html';pp.write_text(pp.read_text()+'\n'+'\n'.join(pops)+'\n')
summaries=[
('Le syndrome associe signes glomérulaires et retentissement aigu ; la cause reste à établir.','EU-SYNDROMES'),
('Ne pas transposer un chiffre de cohorte, de microhématurie ou de progression rapide à tous les syndromes néphritiques suisses.','INT-INFECTION'),
('Lésion du filtre, baisse de filtration et rétention hydrosodée expliquent des signes différents.','EU-HISTO'),
('Sécuriser, localiser, orienter la cause et suivre la dynamique ; mener ces tâches en parallèle si le patient est grave.','CH-URGENCE'),
('La chronologie infectieuse et les signes extrarénaux orientent ; un scénario plausible n’est pas une preuve.','INT-INFECTION'),
('Décrire respiration, conscience, pression, poids, diurèse et indices de cause ; ne pas s’arrêter aux œdèmes.','CH-URGENCE'),
('Néphritique, néphrotique, rapidement progressif et réno-pulmonaire peuvent se superposer.','EU-SYNDROMES'),
('Confirmer les hématies et leur origine ; comparer la créatinine à la base et décider de la biopsie selon le contexte.','CH-SEDIMENT'),
('Chaque examen répond à une question : gravité, localisation, mécanisme ou cause.','INT-GN-GENERAL'),
('Le complément oriente, les anticorps contextualisent ; une infection peut imiter une vascularite.','INT-INFECTION'),
('Soutenir les fonctions vitales, traiter la surcharge et la cause ; pas de corticothérapie universelle.','INT-INFECTION'),
('Suivre fonction, pression, protéines et complément ; une aggravation n’attend pas le contrôle tardif.','INT-INFECTION'),
('L’entraînement fédéral relie un signe à une tâche clinique ; les cas MEDINA ne sont pas des questions officielles.','CH-PROFILES'),
('Ne pas confondre indice et preuve, reprise de diurèse et guérison, code morphologique et diagnostic causal.','EU-IRA')]
paretos=[]
for i,(txt,sid) in enumerate(summaries,1):
 p=CH/('N00_'+('a' if i<=6 else 'b')+'.html');s=BeautifulSoup(p.read_text(),'html.parser');sec=s.find(id='n00-'+str(i));button=s.new_tag('button',attrs={'class':'pareto-btn ui','data-k':'pareto-n00-'+str(i)});button.string='▲ Loi de Pareto — Le raisonnement essentiel';sec.append(button);p.write_text(str(s)+'\n')
 paretos.append('<template data-pop="pareto-n00-'+str(i)+'" data-title="Point essentiel '+str(i)+'"><p>'+txt+'</p><p>Revenir à la section pour les critères, les limites de population et les éléments susceptibles de modifier cette première lecture.</p>'+ref(sid)+'</template>')
pp=CH/'N00_pop2.html';pp.write_text(pp.read_text()+'\n'+'\n'.join(paretos)+'\n')
quizzes=[('Dyspnée et créatinine rapidement ascendante : attendre la sérologie ?','Non : évaluer immédiatement la gravité et organiser les soins urgents.','Oui : la sérologie décide de toute l’orientation.','Le bilan de cause accompagne la stabilisation ; il ne la retarde pas.','CH-URGENCE'),('ANCA positifs avec fièvre et souffle : vascularite certaine ?','Non : une endocardite peut aussi donner des ANCA.','Oui : la positivité exclut une infection.','La microbiologie, le contexte et parfois la biopsie évitent une immunosuppression inadaptée.','INT-INFECTION'),('C3 bas et fonction qui s’aggrave : attendre douze semaines ?','Non : la trajectoire défavorable justifie une réévaluation précoce.','Oui : aucun bilan n’est utile avant ce délai.','Le repère de persistance du complément n’est pas un délai d’attente obligatoire.','INT-INFECTION'),('200mL en8h chez70kg : quelle diurèse pondérale ?','Environ0,36mL/kg/h.','25mL/kg/h.','200÷8=25mL/h ;25÷70≈0,36mL/kg/h.','INT-AKI')]
p=CH/'N00_b.html';s=BeautifulSoup(p.read_text(),'html.parser');sec=s.find(id='n00-13')
for q,yes,no,ex,sid in quizzes:
 markup='<div class="quiz ui"><p>'+q+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid)
 sec.append(BeautifulSoup(markup,'html.parser'))
p.write_text(str(s)+'\n');print('14 fenêtres explicatives,14 Pareto,4 quiz ajoutés ; contrôle encore requis.')
